def solve(shared, per_expert, bytes_per_weight, rank_by_expert, ranks, k, routes):
    integers = (shared, per_expert, bytes_per_weight, ranks, k)
    if any(type(x) is not int for x in integers) or shared < 0 or min(integers[1:]) < 1 or k > len(rank_by_expert):
        raise ValueError("invalid budget")
    weights = [shared * bytes_per_weight for _ in range(ranks)]
    load = [0] * ranks
    for rank in rank_by_expert:
        if type(rank) is not int or not 0 <= rank < ranks:
            raise ValueError("invalid rank")
        weights[rank] += per_expert * bytes_per_weight
    for route in routes:
        if len(route) != k or any(type(e) is not int or not 0 <= e < len(rank_by_expert) for e in route) or len(set(route)) != k:
            raise ValueError("invalid route")
        for expert in route:
            load[rank_by_expert[expert]] += 1
    return weights, shared + k * per_expert, load
